sys_script_include.script:
function GetPluginStatus(aWhitelist)
{
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var GetValue = x_snc_devtools.GetValue;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var Clone = x_snc_devtools.Clone;
	var IsValidSysId = x_snc_devtools.IsValidSysId;
	var IsValidAppName = x_snc_devtools.IsValidAppName;
	var IsValidPluginId = x_snc_devtools.IsValidPluginId;

	aWhitelist = GetArrayValue(aWhitelist);

	if (aWhitelist.length == 0)
	{
		return false;
	}

	var strQuery = '';

	if (aWhitelist.length == 1 && GetValue(aWhitelist,0) == 'all')
	{
		strQuery = 'active=true';
	}
	else
	{
		var aSysIds = [];
		var aIds = [];
		var aNames = [];
		for (var nWhitelist = 0; nWhitelist < aWhitelist.length; nWhitelist++)
		{
			var strWhitelist = aWhitelist[nWhitelist];
			if (IsValidSysId(strWhitelist) == true)
			{
				aSysIds.push(strWhitelist);
			}
			else if (IsValidPluginId(strWhitelist) == true)
			{
				aIds.push(strWhitelist);				
			}
			else if (IsValidAppName(strWhitelist) == true)
			{
				aNames.push(strWhitelist);
			}
			else
			{
				return false;
			}			
		}
		if (aSysIds.length > 0)
		{
			strQuery += 'sys_idIN' + GetStringValue(aSysIds);
		}	
		if (aIds.length > 0)
		{
			if (strQuery != '')
			{
				strQuery += '^OR';
			}
			strQuery += 'sourceIN' + GetStringValue(aIds);
		}		
		if (aNames.length > 0)
		{
			if (strQuery != '')
			{
				strQuery += '^OR';
			}
			strQuery += 'nameIN' + GetStringValue(aNames);
		}		
	}

	var aPlugins = [];

	var grPlugin = new GlideRecord('sys_plugins');
	grPlugin.addEncodedQuery(strQuery);
	grPlugin.query();
	while (grPlugin.next())
	{
		var plugin = Clone(grPlugin);

		delete plugin.sys_meta;
		delete plugin.sys_mod_count;
		delete plugin.sys_tags;

		aPlugins.push(plugin);
	}

	return aPlugins;	
}
